#include "engine_schema.h"
#include <cassert>
#include <cstdio>
using namespace groove;
int main(){for(unsigned e=0;e<instrument_count();++e){const auto& d=*engine_descriptor(e);for(unsigned i=0;i<d.parameters.count;++i){const auto& p=d.parameters.declarations[i];bool core=false;for(auto r:d.page.core)if(r.scope==EngineParameterScope::Engine && r.index==i)core=true;bool envelope=(e==unsigned(Instrument::VirtualAnalog) && i>=11 && i<=14) || ((e==unsigned(Instrument::Additive) || e==unsigned(Instrument::PhaseDist) || e==unsigned(Instrument::Formant) || e==unsigned(Instrument::Granular)) && i>=5 && i<=8);const bool preserved_model_tier=e==unsigned(Instrument::PlaitsMacro) && i==5;assert((p.ui.tier==EngineEditTier::Performance)==(!preserved_model_tier && (core || envelope || e==unsigned(Instrument::Layer))));assert(p.ui.type==declared_parameter_type(p.value,p.choice_count));assert(p.ui.group && *p.ui.group);}for(unsigned i=0;i<engine_schema_count(Instrument(e));++i){auto p=engine_schema_parameter(Instrument(e),i);assert(p.value && p.ui.group && p.value->unit);assert(p.value->minimum<=p.value->initial && p.value->initial<=p.value->maximum);}}std::puts("Editor schema: CORE classification, type, range, unit, group and shared references passed");}
